mapper.select:
SELECT id, user_id, seat_id, start_time, end_time, status, check_in_time, cancel_time, create_time, update_time
FROM reservation
WHERE id = #{id}

SELECT id, user_id, seat_id, start_time, end_time, status, check_in_time, cancel_time, create_time, update_time
FROM reservation
WHERE seat_id = #{seatId}
  AND status IN ('reserved', 'checked_in')
  AND start_time < #{endTime}
  AND end_time > #{startTime}

SELECT id, user_id, seat_id, start_time, end_time, status, check_in_time, cancel_time, create_time, update_time
FROM reservation
WHERE seat_id = #{seatId}
  AND status IN ('reserved', 'checked_in')
  AND start_time <= #{now}
  AND end_time > #{now}
ORDER BY FIELD(status, 'checked_in', 'reserved'), start_time ASC
LIMIT 1
